#include "AudioToNotes.h"
static AudioBuffer<float> melodyFixture(double rate,bool antiPhase=true){
    AudioBuffer<float> audio(2,(int)std::llround(rate*1.8));audio.clear();int pitches[]={60,64,67};double starts[]={.2,.75,1.25},ends[]={.6,1.1,1.65};for(int n=0;n<3;++n)for(int i=(int)std::llround(starts[n]*rate);i<(int)std::llround(ends[n]*rate);++i){double t=i/rate-starts[n],length=ends[n]-starts[n],gain=jmin(1.,t/.005,(length-t)/.005),hz=440*std::pow(2.,(pitches[n]-69)/12.);float sample=(float)(.25*gain*(std::sin(2*MathConstants<double>::pi*hz*t)+.18*std::sin(4*MathConstants<double>::pi*hz*t)));audio.setSample(0,i,sample);audio.setSample(1,i,antiPhase?-sample:sample);}return audio;
}
static void testAudioToNotes(const File& root,Assets& assets){
    TranscriptionOptions options;MelodyTranscript result;auto audio=melodyFixture(48000);auto original=audio.getSample(0,15000);std::atomic<float> progress{0};
    expect(transcribeMelody(audio,48000,options,result,nullptr,&progress).wasOk(),"monophonic audio conversion detects a generated three-note melody");
    expect(result.notes.size()==3&&result.notes[0].note.pitch==60&&result.notes[1].note.pitch==64&&result.notes[2].note.pitch==67,"analytic C4 E4 G4 corpus has exact note-count and pitch labels");
    if(result.notes.size()==3){double starts[]={.2,.75,1.25},ends[]={.6,1.1,1.65};for(int n=0;n<3;++n){auto row=result.notes[(size_t)n];expect(std::abs(row.note.beat/2-starts[n])<=.08&&std::abs((row.note.beat+row.note.length)/2-ends[n])<=.08,"generated corpus onset and offset estimates stay within 80 ms");expect(row.confidence>=options.confidence&&row.confidence<=1&&row.note.velocity>.1&&row.note.velocity<=.95&&row.note.probability==1,"periodicity is separate from playable velocity and note probability");}}
    expect(progress.load()==1&&audio.getSample(0,15000)==original&&result.seconds==1.8&&result.voiced>0&&result.channel==0,"transcription commits complete measurements without modifying source audio");
    Array<var> evaluation;bool corpusPassed=true;
    auto record=[&](double rate,const MelodyTranscript& transcript){auto* row=new DynamicObject();row->setProperty("sampleRate",rate);Array<var> observed;bool ok=transcript.notes.size()==3;double starts[]={.2,.75,1.25},ends[]={.6,1.1,1.65};int pitches[]={60,64,67};for(size_t i=0;i<transcript.notes.size();++i){const auto& n=transcript.notes[i];auto* v=new DynamicObject();v->setProperty("pitch",n.note.pitch);v->setProperty("onsetSeconds",n.note.beat/2);v->setProperty("offsetSeconds",(n.note.beat+n.note.length)/2);v->setProperty("periodicity",n.confidence);observed.add(var(v));if(i<3)ok&=n.note.pitch==pitches[i]&&std::abs(n.note.beat/2-starts[i])<=.08&&std::abs((n.note.beat+n.note.length)/2-ends[i])<=.08;}row->setProperty("observed",observed);row->setProperty("passed",ok);corpusPassed&=ok;evaluation.add(var(row));return ok;};
    record(48000,result);
    auto retained=result;std::atomic<bool> cancel{true};expect(transcribeMelody(audio,48000,options,result,&cancel).failed()&&transcriptionSummary(result)==transcriptionSummary(retained),"pre-cancelled transcription retains previous notes atomically");
    auto quiet=audio;quiet.applyGain(.0001f);expect(transcribeMelody(quiet,48000,options,result).failed()&&transcriptionSummary(result)==transcriptionSummary(retained),"RMS gate rejects inaudible selections without replacing a prior result");
    AudioBuffer<float> dc(2,24000);for(int c=0;c<2;++c)for(int i=0;i<24000;++i)dc.setSample(c,i,.3f);expect(transcribeMelody(dc,48000,options,result).failed(),"DC-only audio cannot become an invented melody");
    auto noise=dc;Random random(192837);for(int c=0;c<2;++c)for(int i=0;i<noise.getNumSamples();++i)noise.setSample(c,i,random.nextFloat()*.4f-.2f);expect(transcribeMelody(noise,48000,options,result).failed(),"deterministic broadband noise has no accepted stable melody");
    auto invalid=audio;invalid.setSample(1,500,std::numeric_limits<float>::quiet_NaN());expect(transcribeMelody(invalid,48000,options,result).failed(),"non-finite audio in either stereo channel is rejected");
    for(double rate:{8000.,44100.,96000.}){auto signal=melodyFixture(rate);MelodyTranscript converted;expect(transcribeMelody(signal,rate,options,converted).wasOk()&&converted.notes.size()==3&&converted.notes[0].note.pitch==60&&converted.notes[1].note.pitch==64&&converted.notes[2].note.pitch==67&&record(rate,converted),"sample-rate conversion retains generated pitches and 80 ms timing targets at 8/44.1/96 kHz");}
    auto* corpus=new DynamicObject();corpus->setProperty("corpus","synthetic C4/E4/G4; 1.8 s; 120 BPM; 5 ms edges; 18% second harmonic; anti-phase stereo");corpus->setProperty("expectedPitches",var(Array<var>{60,64,67}));corpus->setProperty("expectedOnsetsSeconds",var(Array<var>{.2,.75,1.25}));corpus->setProperty("expectedOffsetsSeconds",var(Array<var>{.6,1.1,1.65}));corpus->setProperty("timingToleranceSeconds",.08);corpus->setProperty("cases",evaluation);corpus->setProperty("passed",corpusPassed);expect(root.getChildFile("audio-to-notes-evaluation.json").replaceWithText(JSON::toString(var(corpus),false,22))&&corpusPassed,"synthetic evaluation publishes exact observed pitches timing confidence and declared targets");
    auto offset=audio;for(int i=0;i<offset.getNumSamples();++i){offset.setSample(0,i,.1f);offset.setSample(1,i,audio.getSample(1,i)+.2f);}MelodyTranscript right;expect(transcribeMelody(offset,48000,options,right).wasOk()&&right.channel==1&&right.notes.size()==3,"highest-AC channel selection retains anti-phase/right-only melody despite DC offsets");
    for(double hz:{40.,2200.}){AudioBuffer<float> outOfRange(2,24000);for(int i=0;i<24000;++i)for(int c=0;c<2;++c)outOfRange.setSample(c,i,.3f*(float)std::sin(2*MathConstants<double>::pi*hz*i/48000));expect(transcribeMelody(outOfRange,48000,options,result).failed(),"pure tones outside the declared 55-1600 Hz range are rejected");}
    auto bad=options;bad.confidence=.64;expect(validateTranscription(bad).failed(),"confidence lower bound prevents unsupported detection thresholds");bad=options;bad.minMs=501;expect(validateTranscription(bad).failed(),"minimum-note duration is bounded");bad=options;bad.gateDb=std::numeric_limits<double>::infinity();expect(validateTranscription(bad).failed(),"non-finite gate settings fail validation");
    auto song=emptyProject();song.bpm=120;song.songMode=true;song.patterns[0].lanes[7]={{0,1,72,.6f}};Project next;auto before=JSON::toString(projectToJson(song));expect(appendTranscription(song,retained,7,"Detected melody",next).wasOk()&&next.patterns.size()==song.patterns.size()+1&&!next.songMode&&next.activePattern==(int)song.patterns.size(),"Apply candidate appends a new active PAT pattern without replacing an existing lane");
    expect(next.patterns.back().lanes[7].size()==3&&next.patterns[0].lanes[7]==song.patterns[0].lanes[7]&&next.clips.size()==song.clips.size()&&JSON::toString(projectToJson(song))==before,"generated notes preserve source project, existing notes and Playlist links");
    auto rendered=render(next,assets,root,48000);expect(rendered.getMagnitude(0,0,48000)>.001f,"transcribed pattern reaches actual instrument playback");Project loaded;expect(projectFromJson(projectToJson(next),loaded).wasOk()&&loaded.patterns.back().lanes[7]==next.patterns.back().lanes[7]&&(int)projectToJson(next)["schema"]==projectSchema,"transcribed notes round-trip through the current project schema");
    auto full=song;while(full.patterns.size()<maxPatterns)full.patterns.push_back(full.patterns[0]);auto sentinel=JSON::toString(projectToJson(next));expect(appendTranscription(full,retained,7,"No slot",next).failed()&&JSON::toString(projectToJson(next))==sentinel,"pattern-capacity failures never partly modify the destination project");song.tracks[7].isBus=true;expect(appendTranscription(song,retained,7,"Bus",next).failed(),"note transcription cannot target mixer buses");song.tracks[7].isBus=false;song.bpm=100;expect(appendTranscription(song,retained,7,"Stale tempo",next).failed(),"tempo changes reject stale timing estimates");
    auto report=root.getChildFile("transcription-core-report.json"),source=root.getChildFile("analytic-melody.wav");String hash=String::repeatedString("a",64);expect(saveTranscriptionReport(report,retained,options,source,hash,9600,48000).wasOk(),"source identity, offsets and per-note confidence persist in a separate report");auto json=JSON::parse(report);expect(json["notes"].getArray()->size()==3&&(int)json["sourceFirstFrame"]==9600&&json["notes"][0]["confidence"].isDouble()&&json["summary"].toString().contains("not a guarantee"),"review report keeps uncertainty explicit and stores source selection provenance");auto previous=report.loadFileAsString();auto broken=retained;broken.notes[0].confidence=2;expect(saveTranscriptionReport(report,broken,options,source,hash,0,48000).failed()&&report.loadFileAsString()==previous,"invalid confidence cannot overwrite an existing transcription report");
}
